 const p=new Promise((resolve,reject)=>{const image=new Image();image.onload=()=>{images.set(url,image);pending.delete(url);resolve(image);};image.onerror=()=>{pending.delete(url);reject(new Error('No se pudo cargar '+url));};image.src=url;});pending.set(url,p);return p;
