 point(clientX,clientY){const r=this.canvas.getBoundingClientRect(),sx=(clientX-r.x-this.w/2)/(this.tile/2),sy=(clientY-r.y-this.h*.49)/(this.rh/2);return{x:this.focus.x+(sx+sy)/2,y:this.focus.z+(sy-sx)/2};}
 bind(){let drag=null,pinch=null;const pointers=new Map();this.canvas.addEventListener('contextmenu',e=>e.preventDefault());this.canvas.addEventListener('pointerdown',e=>{this.canvas.setPointerCapture(e.pointerId);pointers.set(e.pointerId,{x:e.clientX,y:e.clientY});if(pointers.size===2){const p=[...pointers.values()];pinch=Math.hypot(p[0].x-p[1].x,p[0].y-p[1].y);drag=null;return;}drag={x:e.clientX,y:e.clientY,lx:e.clientX,ly:e.clientY,button:e.button,moved:false,pan:e.altKey||e.button===1||e.pointerType==='touch'||this.panMode};});this.canvas.addEventListener('pointermove',e=>{if(pointers.has(e.pointerId))pointers.set(e.pointerId,{x:e.clientX,y:e.clientY});if(pointers.size===2){const p=[...pointers.values()],d=Math.hypot(p[0].x-p[1].x,p[0].y-p[1].y);if(pinch)this.zoom=clamp(this.zoom*d/pinch,.5,2.1);pinch=d;this.updateCamera();return;}this.hover=this.point(e.clientX,e.clientY);if(!drag)return;if(Math.hypot(e.clientX-drag.x,e.clientY-drag.y)>7)drag.moved=true;if(drag.moved&&drag.pan){const dx=(e.clientX-drag.lx)/(this.tile/2),dy=(e.clientY-drag.ly)/(this.rh/2);this.focus.x=clamp(this.focus.x-(dx+dy)/2,-6,SIZE+6);this.focus.z=clamp(this.focus.z-(dy-dx)/2,-6,SIZE+6);}else if(drag.moved)this.selectionRect={x:drag.x,y:drag.y,x2:e.clientX,y2:e.clientY};drag.lx=e.clientX;drag.ly=e.clientY;});this.canvas.addEventListener('pointerup',e=>{pointers.delete(e.pointerId);if(pointers.size<2)pinch=null;if(!drag)return;if(drag.moved&&!drag.pan){const r=this.canvas.getBoundingClientRect();this.onPick({box:{x1:Math.min(drag.x,e.clientX)-r.x,y1:Math.min(drag.y,e.clientY)-r.y,x2:Math.max(drag.x,e.clientX)-r.x,y2:Math.max(drag.y,e.clientY)-r.y},append:e.shiftKey});}else if(!drag.moved){const hit=this.hit(e.clientX,e.clientY);this.onPick({...this.point(e.clientX,e.clientY),...hit,button:drag.button,append:e.shiftKey});}drag=null;this.selectionRect=null;});this.canvas.addEventListener('pointercancel',()=>{drag=null;pinch=null;pointers.clear();this.selectionRect=null;});this.canvas.addEventListener('wheel',e=>{e.preventDefault();const before=this.point(e.clientX,e.clientY);this.zoom=clamp(this.zoom-e.deltaY*.001,.5,2.1);this.updateCamera();const after=this.point(e.clientX,e.clientY);this.focus.x+=before.x-after.x;this.focus.z+=before.y-after.y;},{passive:false});}
 hit(clientX,clientY){const r=this.canvas.getBoundingClientRect(),x=clientX-r.x,y=clientY-r.y;for(const s of [...(this.pickSprites||[])].reverse()){if(x>=s.x&&x<=s.x+s.w&&y>=s.y&&y<=s.y+s.h){const px=Math.floor(s.frame[0]+(x-s.x)/s.w*s.frame[2]),py=Math.floor(s.frame[1]+(y-s.y)/s.h*s.frame[3]);try{if(!s.mask){s.mask=document.createElement('canvas');s.mask.width=s.image.width;s.mask.height=s.image.height;s.mask.getContext('2d').drawImage(s.image,0,0);}if(s.mask.getContext('2d').getImageData(px,py,1,1).data[3]<32)continue;}catch{}return{x:s.worldX,y:s.worldY};}}return{};}
